/bin/bash -lc "python - <<'PY'
import inspect
from bioblend.galaxy.histories import HistoryClient
from bioblend.galaxy.dataset_collections import DatasetCollectionClient
print([n for n in dir(HistoryClient) if 'dataset' in n or 'content' in n])
print([n for n in dir(DatasetCollectionClient) if not n.startswith('_')])
for cls,names in [(HistoryClient,['update_dataset','update_dataset_collection','show_dataset']), (DatasetCollectionClient,['create_dataset_collection','create_list','show_dataset_collection'])]:
 for n in names:
  if hasattr(cls,n): print(cls.__name__,n,inspect.signature(getattr(cls,n)))
PY"

