/bin/bash -lc "python - <<'PY'
import csv,collections
p='galaxy_outputs/blm_carriers_concat.tsv'
allrows=[]
with open(p,newline='') as f:
 for r in csv.reader(f,delimiter='\\t'):
  if len(r)<15: continue
  try:v=float(r[9])
  except:continue
  if v<0.3 and r[13] in {'synonymous_variant','missense_variant'}: allrows.append(r)
print('observations',len(allrows),'syn',sum(r[13]=='synonymous_variant' for r in allrows))
keys={(r[0],r[1],r[13]) for r in allrows}
print('unique variants',len(keys),'syn',sum(k[2]=='synonymous_variant' for k in keys))
for k,n in collections.Counter((r[0],r[1],r[13]) for r in allrows).most_common():
 if n>1: print(n,k)
PY"

